import * as pdfjs from './vendor/pdf.min.mjs';
pdfjs.GlobalWorkerOptions.workerSrc = new URL('./vendor/pdf.worker.min.mjs', import.meta.url).href;
const KEY='hogar-vault-v1', encoder=new TextEncoder(), decoder=new TextDecoder();
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), today=()=>new Date().toLocaleDateString('en-CA'), monthNow=()=>today().slice(0,7), money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:2}).format(Number(n)||0), usd=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n)||0), number=n=>Number(String(n??'').replace(',','.'))||0;
const defaultCategories=()=>[['servicios','Servicios'],['supermercado','Supermercado'],['hogar','Hogar'],['salud','Salud'],['transporte','Transporte'],['educacion','Educación'],['otros','Otros']].map(([id,name])=>({id:'cat-'+id,name}));
const defaultPayees=()=>[['edenor','Edenor','cat-servicios'],['aysa','AySA','cat-servicios'],['coto','Coto','cat-supermercado']].map(([id,name,categoryId])=>({id:'payee-'+id,name,categoryId}));
const normalizeState=data=>{if(!Array.isArray(data.expenseCategories))data.expenseCategories=defaultCategories();if(!Array.isArray(data.payees))data.payees=defaultPayees();data.accounts=(data.accounts||[]).map(a=>({...a,cbu:a.cbu||'',debitLast:a.debitLast||'',usdOpening:number(a.usdOpening)}));data.cards=(data.cards||[]).map(c=>({...c,active:c.active!==false}));data.charges=(data.charges||[]).map(c=>({...c,usdAmount:number(c.usdAmount)}));data.statements=(data.statements||[]).map(s=>({...s,usdAmount:number(s.usdAmount)}));return data};
const initial=()=>normalizeState({version:1,accounts:[['Banco Nación (nuevo)','bank','#2073ad'],['Banco Nación (viejo)','bank','#4987bc'],['Banco Patagonia','bank','#4b8a47'],['Santander','bank','#db323e'],['ICBC','bank','#8065b2'],['Mercado Pago','wallet','#10a5ac'],['Personal Pay','wallet','#2b7789'],['Naranja X','wallet','#ff7942'],['Efectivo','cash','#677d8b']].map(([name,type,color])=>({id:uid(),name,type,color,opening:0})),cards:[],members:['Yo'],transactions:[],charges:[],statements:[],loans:[],bills:[]});
let state=null,secret=null,salt=null,view='inicio',selectedMonth=monthNow(),docDraft=null,noticeTimer=null,homeAmountsVisible=true;
const enc64=a=>btoa(String.fromCharCode(...new Uint8Array(a))), dec64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function derive(pass,s){let k=await crypto.subtle.importKey('raw',encoder.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:310000,hash:'SHA-256'},k,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encrypted(data,key,s){const iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,encoder.encode(JSON.stringify(data)));return {format:'hogar-cifrado',version:1,kdf:'PBKDF2-SHA256',iterations:310000,salt:enc64(s),iv:enc64(iv),data:enc64(cipher)}}
async function unlocked(blob,pass){if(blob?.format!=='hogar-cifrado'||blob?.version!==1||!blob.salt||!blob.iv||!blob.data)throw Error('Archivo de respaldo no reconocido.');const s=dec64(blob.salt),k=await derive(pass,s),bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:dec64(blob.iv)},k,dec64(blob.data));const data=JSON.parse(decoder.decode(bytes));if(!Array.isArray(data.accounts)||!Array.isArray(data.transactions)||!Array.isArray(data.cards))throw Error('Datos no válidos.');return {data:normalizeState(data),key:k,s}}
async function save(){if(!state||!secret)return;localStorage.setItem(KEY,JSON.stringify(await encrypted(state,secret,salt)))}
function toast(msg){const el=$('#notice');el.textContent=msg;el.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.hidden=true,5500)}
function start(){ $('#auth').hidden=true;$('#app').hidden=false;$('#month').value=selectedMonth; render() }
function authMode(){const exists=!!localStorage.getItem(KEY);$('#auth-title').textContent=exists?'Bienvenida de nuevo':'Finanzas';$('#auth-help').textContent=exists?'Ingresá tu contraseña para abrir tus datos.':'Creá una contraseña de al menos 8 caracteres para proteger tus datos en esta computadora.';$('#auth-button').textContent=exists?'Abrir mi espacio':'Crear espacio';$('#confirm-wrap').hidden=exists;$('#confirm-password').required=!exists}
authMode();$('#auth-form').onsubmit=async e=>{e.preventDefault();const pass=$('#password').value,err=$('#auth-error');err.textContent='';$('#auth-button').disabled=true;try{let raw=localStorage.getItem(KEY);if(raw){const result=await unlocked(JSON.parse(raw),pass);state=result.data;secret=result.key;salt=result.s}else{if(pass!==$('#confirm-password').value)throw Error('Las contraseñas no coinciden.');salt=crypto.getRandomValues(new Uint8Array(16));secret=await derive(pass,salt);state=initial();await save()}start()}catch(ex){err.textContent=ex.name==='OperationError'?'Contraseña incorrecta o archivo dañado.':ex.message}finally{$('#auth-button').disabled=false}};
$('#lock').onclick=()=>{state=null;secret=null;$('#app').hidden=true;$('#auth').hidden=false;$('#password').value='';authMode()};
$('#month').onchange=e=>{selectedMonth=e.target.value||monthNow();render()};$('#add-main').onclick=()=>openTransaction();$('#nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render()}};
const byId=(arr,id)=>arr.find(x=>x.id===id), accountName=id=>byId(state.accounts,id)?.name||'Cuenta eliminada', accountColor=id=>byId(state.accounts,id)?.color||'#087894', cardName=id=>byId(state.cards,id)?.name||'Tarjeta eliminada';
const nameSorter=new Intl.Collator('es-AR',{sensitivity:'base',numeric:true});
const txMonth=t=>t.date?.slice(0,7), inMonth=t=>txMonth(t)===selectedMonth;
function balance(a){return accountBalanceThrough(a)}
function accountDelta(a,m=selectedMonth){return state.transactions.filter(t=>t.accountId===a.id&&txMonth(t)===m).reduce((n,t)=>n+(t.kind==='income'||t.kind==='transfer_in'?number(t.amount):-number(t.amount)),0)}
function accountBalanceThrough(a,m=selectedMonth){return number(a.opening)+state.transactions.filter(t=>txMonth(t)<=m).reduce((n,t)=>n+(t.accountId===a.id?(t.kind==='income'||t.kind==='transfer_in'?number(t.amount):-number(t.amount)):0),0)}
function accountDisplayBalance(a,m=selectedMonth){return m>monthNow()?accountDelta(a,m):accountBalanceThrough(a,m)}
const homeMoney=n=>homeAmountsVisible?money(n):'$ --';
const homeUsd=n=>homeAmountsVisible?usd(n):'US$ --';
const amountPair=(ars,usdAmount,empty='—')=>{const a=number(ars),u=number(usdAmount),parts=[];if(a>0)parts.push(money(a));if(u>0)parts.push(usd(u));return parts.join(' + ')||empty};
const homeAmountPair=(ars,usdAmount,empty='—')=>{const a=number(ars),u=number(usdAmount),parts=[];if(a>0)parts.push(homeMoney(a));if(u>0)parts.push(homeUsd(u));return parts.join(' + ')||empty};
const trType=t=>({income:'Ingreso',expense:'Gasto',transfer_out:'Transferencia',transfer_in:'Transferencia recibida',card_payment:'Pago de tarjeta',loan_payment:'Cuota de préstamo'}[t.kind]||t.kind);
function accountOptions(selected='',all=false,showBalance=false){return (all?'<option value="">Todas las cuentas</option>':'<option value="">Elegí una cuenta</option>')+state.accounts.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)}${showBalance?' · saldo '+money(accountBalanceThrough(a,monthNow())):''}</option>`).join('')}
const cardOptions=(selected='',includeInactive=false)=>'<option value="">Elegí una tarjeta</option>'+state.cards.filter(c=>c.active!==false||includeInactive||selected===c.id).map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}${c.active===false?' (de baja)':''}</option>`).join('');
const memberOptions=(selected=state.members[0]||'Yo')=>state.members.map(m=>`<option ${selected===m?'selected':''}>${esc(m)}</option>`).join('');
const categoryName=id=>byId(state.expenseCategories,id)?.name||'Sin rubro';
const payeeName=id=>byId(state.payees,id)?.name||'';
const categoryOptions=(selected='')=>'<option value="">Elegí un rubro</option>'+state.expenseCategories.map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''}>${esc(c.name)}</option>`).join('');
const payeeOptions=(selected='')=>'<option value="">Otro / sin guardar</option>'+state.payees.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.name)}</option>`).join('');
const cardDisplaySort=(a,b)=>nameSorter.compare(accountName(a.accountId),accountName(b.accountId))||nameSorter.compare(a.name,b.name);
function render(){if(!state)return;$('#page-title').textContent=({inicio:'Resumen',movimientos:'Movimientos',tarjetas:'Tarjetas',vencimientos:'Vencimientos',prestamos:'Préstamos',documentos:'Leer documentos',configuracion:'Cuentas, rubros y respaldo'})[view];$('#month').value=selectedMonth;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#view').innerHTML=({inicio:renderHome,movimientos:renderTransactions,tarjetas:renderCards,vencimientos:renderDues,prestamos:renderLoans,documentos:renderDocuments,configuracion:renderSettings})[view]();cleanBackupControls();wire()}
const rowsOrEmpty=(html,msg)=>html||`<div class="empty"><strong>Todavía no hay datos</strong>${msg}</div>`;
function expenseSummaryHtml(){
  const totals=new Map();
  for(const t of state.transactions.filter(t=>inMonth(t)&&t.kind==='expense')){
    const key=t.expenseCategoryId||'sin-rubro';
    totals.set(key,(totals.get(key)||0)+number(t.amount));
  }
  if(!totals.size)return '';
  const rows=[...totals].sort((a,b)=>b[1]-a[1]);
  return `<div class="section-head"><div><h2>Gastos por rubro</h2><p>Gastos pagados desde cuentas en ${formatMonth(selectedMonth)}. Los pagos de tarjeta se muestran aparte.</p></div></div><div class="panel">${rows.map(([id,amount])=>`<div class="list-row"><strong>${esc(id==='sin-rubro'?'Sin rubro':categoryName(id))}</strong><strong>${homeMoney(amount)}</strong></div>`).join('')}</div>`;
}
function renderHome(){const tx=state.transactions.filter(inMonth),incomes=tx.filter(t=>t.kind==='income').reduce((a,t)=>a+number(t.amount),0),out=tx.filter(t=>['expense','card_payment','loan_payment'].includes(t.kind)).reduce((a,t)=>a+number(t.amount),0),forecast=state.charges.filter(c=>c.month===nextMonth(selectedMonth)).reduce((a,c)=>a+number(c.amount),0),forecastUsd=state.charges.filter(c=>c.month===nextMonth(selectedMonth)).reduce((a,c)=>a+number(c.usdAmount),0),balances=state.accounts.reduce((a,b)=>a+accountDisplayBalance(b),0),futureMonth=selectedMonth>monthNow();const recent=tx.filter(t=>t.kind!=='transfer_in').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6),dues=dueItems().filter(x=>!x.paid).slice(0,4);return `<div class="home-summary ${homeAmountsVisible?'':'amounts-hidden'}"><div class="section-head home-privacy"><div></div><button class="secondary small-action" data-toggle-home-amounts="1">${homeAmountsVisible?'Ocultar montos':'Mostrar montos'}</button></div><div class="grid-cards"><div class="metric"><span>${futureMonth?'Movimiento neto en cuentas':'Disponible en cuentas'}</span><strong class="${balances<0?'negative':''}">${homeMoney(balances)}</strong><small>${futureMonth?'Solo movimientos cargados en este mes':'Saldo al cierre de '+formatMonth(selectedMonth)}</small></div><div class="metric"><span>Ingresos del mes</span><strong class="positive">${homeMoney(incomes)}</strong></div><div class="metric"><span>Salidas del mes</span><strong>${homeMoney(out)}</strong><small>Gastos y pagos desde cuentas</small></div><div class="metric"><span>Tarjetas · mes siguiente</span><strong>${forecastUsd>0?homeAmountPair(forecast,forecastUsd):homeMoney(forecast)}</strong><small>Consumos cargados para ${formatMonth(nextMonth(selectedMonth))}</small></div></div><div class="section-head"><div><h2>Cuentas y billeteras</h2><p>${futureMonth?'Movimientos cargados en '+formatMonth(selectedMonth):'Saldo de cada cuenta al cierre de '+formatMonth(selectedMonth)}</p></div><button class="text-button" data-go="configuracion">Administrar</button></div><div class="account-grid">${state.accounts.map(a=>{const b=accountDisplayBalance(a),delta=accountDelta(a),meta=[a.cbu?`CBU/Alias: ${esc(a.cbu)}`:'',a.debitLast?`Débito: **** ${esc(a.debitLast)}`:''].filter(Boolean).join(' · ');return `<div class="account-card" style="--accent:${esc(a.color)}"><div class="top"><strong>${esc(a.name)}</strong><small>${a.type==='wallet'?'Billetera':a.type==='cash'?'Efectivo':'Banco'}</small></div><div class="amount ${b<0?'negative':''}">${homeMoney(b)}</div>${number(a.usdOpening)>0?`<div class="amount usd-amount">${homeUsd(a.usdOpening)}</div><small class="account-detail">Caja de ahorro en dólares</small>`:''}<small class="account-detail">Movimiento del mes: ${homeMoney(delta)}</small>${meta?`<small class="account-detail">${meta}</small>`:''}</div>`}).join('')}</div><div class="two-col"><div><div class="section-head"><h2>Últimos movimientos del mes</h2><button class="text-button" data-go="movimientos">Ver todos</button></div><div class="panel">${rowsOrEmpty(recent.map(t=>`<div class="list-row"><div><strong>${esc(t.description||trType(t))}</strong><small>${esc(accountName(t.accountId))} · ${formatDate(t.date)} · ${esc(t.member||'')}</small></div><strong class="right ${t.kind==='income'?'positive':''}">${t.kind==='income'?'+':'−'}${homeMoney(t.amount)}</strong></div>`).join(''),'Cargá un ingreso, gasto o transferencia para empezar.')}</div></div><div><div class="section-head"><h2>Próximos vencimientos</h2><button class="text-button" data-go="vencimientos">Ver todos</button></div><div class="panel">${rowsOrEmpty(dues.map(d=>`<div class="list-row"><div><strong>${esc(d.name)}</strong><small>${formatDate(d.date)} · ${esc(d.detail)}</small></div><div class="right"><strong>${homeAmountPair(d.amount,d.usdAmount,'—')}</strong><br><span class="badge ${d.date<today()?'overdue':''}">${d.date<today()?'Vencido':'Pendiente'}</span></div></div>`).join(''),'Cargá fechas en tarjetas, facturas o préstamos.')}</div></div></div>${expenseSummaryHtml()}</div>`}
function renderTransactions(){let arr=state.transactions.filter(t=>inMonth(t)&&t.kind!=='transfer_in').sort((a,b)=>b.date.localeCompare(a.date));return `<div class="filters"><button class="primary" data-action="new-transaction">+ Movimiento</button><button class="secondary" data-go="configuracion">Administrar rubros</button><select id="filter-account" aria-label="Filtrar por cuenta">${accountOptions('',true)}</select><select id="filter-kind" aria-label="Filtrar por tipo"><option value="">Todos los tipos</option><option value="income">Ingresos</option><option value="expense">Gastos</option><option value="transfer_out">Transferencias</option><option value="card_payment">Pagos de tarjeta</option><option value="loan_payment">Cuotas de préstamo</option></select></div><div id="tx-results">${txTable(arr)}</div><p class="footnote">Las transferencias mueven dinero entre cuentas y no se suman a ingresos ni gastos del hogar. Los pagos de tarjeta descuentan el saldo pendiente del resumen indicado.</p>`}
function txTable(arr){return arr.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Detalle</th><th>Cuenta</th><th>Tipo</th><th>Persona</th><th class="right">Importe</th><th></th></tr></thead><tbody>${arr.map(t=>`<tr><td>${formatDate(t.date)}</td><td><strong>${esc(t.description||trType(t))}</strong>${t.cardId?`<br><small>${esc(cardName(t.cardId))} · ${esc(t.statementMonth||'')}</small>`:''}</td><td>${esc(accountName(t.accountId))}</td><td>${esc(trType(t))}${t.kind==='expense'?` · ${esc(categoryName(t.expenseCategoryId))}${t.payeeId?' · '+esc(payeeName(t.payeeId)):''}`:t.category?` · ${esc(t.category)}`:''}${t.kind==='transfer_out'?` → <span class="transfer-target" style="color:${esc(accountColor(t.toAccountId))}">${esc(accountName(t.toAccountId))}</span>`:''}</td><td>${esc(t.member||'')}</td><td class="right ${['income','transfer_in'].includes(t.kind)?'positive':''}">${['income','transfer_in'].includes(t.kind)?'+':'−'}${money(t.amount)}</td><td>${t.kind==='expense'?`<button class="text-button small-action" data-classify-tx="${t.id}">Clasificar</button>`:''}<button class="text-button small-action" data-delete-tx="${t.id}">Borrar</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Sin movimientos para ${formatMonth(selectedMonth)}</strong>Podés cargar movimientos y consultar otros meses con el selector de arriba.</div>`}
function nextMonth(m){const [y,mo]=m.split('-').map(Number);return `${y+(mo===12?1:0)}-${String(mo===12?1:mo+1).padStart(2,'0')}`};function formatMonth(m){if(!/^\d{4}-\d{2}$/.test(m||''))return '—';return new Date(`${m}-01T12:00:00`).toLocaleDateString('es-AR',{month:'long',year:'numeric'})}function formatDate(d){if(!d)return 'Sin fecha';const [y,m,day]=d.split('-');return `${day}/${m}/${y}`}
function cardStatement(c,m=selectedMonth){return byId(state.statements.filter(s=>s.month===m),c.id)||null}
function dueForCard(c,m=selectedMonth){const s=state.statements.find(s=>s.cardId===c.id&&s.month===m);const paid=state.transactions.filter(t=>t.kind==='card_payment'&&t.cardId===c.id&&t.statementMonth===m).reduce((x,t)=>x+number(t.amount),0);return {total:number(s?.amount),usdTotal:number(s?.usdAmount),paid,remaining:number(s?.amount)-paid,due:s?.due||''}}
function renderCards(){let nm=nextMonth(selectedMonth),statementAll=state.statements.filter(s=>s.month===selectedMonth).reduce((n,s)=>n+number(s.amount),0),statementUsd=state.statements.filter(s=>s.month===selectedMonth).reduce((n,s)=>n+number(s.usdAmount),0),all=state.cards.reduce((a,c)=>a+state.charges.filter(x=>x.cardId===c.id&&x.month===nm).reduce((n,x)=>n+number(x.amount),0),0),allUsd=state.cards.reduce((a,c)=>a+state.charges.filter(x=>x.cardId===c.id&&x.month===nm).reduce((n,x)=>n+number(x.usdAmount),0),0),cards=[...state.cards].sort(cardDisplaySort);return `<div class="section-head"><div><h2>Consumos para ${formatMonth(nm)}</h2><p>La próxima liquidación se estima con los consumos que cargues. El resumen actual se ingresa cuando lo recibís.</p></div><button class="primary" data-action="new-card">+ Tarjeta</button></div><div class="grid-cards total-grid"><div class="metric"><span>Total de resúmenes de ${formatMonth(selectedMonth)}</span><strong>${statementUsd>0?amountPair(statementAll,statementUsd):money(statementAll)}</strong></div><div class="metric"><span>Estimado total del mes siguiente</span><strong>${allUsd>0?amountPair(all,allUsd):money(all)}</strong><small>Consumos para ${formatMonth(nm)}</small></div></div>${cards.length?`<div class="card-grid">${cards.map(c=>{const a=byId(state.accounts,c.accountId),d=dueForCard(c),statement=state.statements.find(s=>s.cardId===c.id&&s.month===selectedMonth),hasStatement=!!statement,charges=state.charges.filter(x=>x.cardId===c.id&&x.month===nm),future=charges.reduce((n,x)=>n+number(x.amount),0),futureUsd=charges.reduce((n,x)=>n+number(x.usdAmount),0);return `<div class="card-tile ${c.active===false?'inactive':''}" style="--accent:${esc(a?.color||'#638da5')}"><div class="heading"><div><h3>${esc(c.name)} ${c.active===false?'<span class="badge">De baja</span>':''}</h3><small class="muted">${esc(a?.name||'Sin banco')}</small></div><button class="text-button small-action" data-edit-card="${c.id}">Editar</button></div><div class="card-stats"><div><span>Resumen ${formatMonth(selectedMonth)}</span><strong>${hasStatement?amountPair(d.total,d.usdTotal):'Sin cargar'}</strong></div><div><span>Pagado</span><strong>${money(d.paid)}</strong></div><div><span>Queda por pagar</span><strong class="${d.remaining<0?'positive':''}">${hasStatement&&(d.total>0||d.paid>0)?money(d.remaining):'—'}</strong></div></div>${charges.slice(0,4).map(x=>`<div class="list-row"><div><strong>${esc(x.description)}</strong><small>${esc(x.installment||'')} ${x.member?'· '+esc(x.member):''}${x.expenseCategoryId?' · '+esc(categoryName(x.expenseCategoryId)):''}</small></div><div class="right"><strong>${amountPair(x.amount,x.usdAmount)}</strong><br><button class="text-button small-action" data-edit-charge="${x.id}">Editar</button> <button class="text-button small-action" data-delete-charge="${x.id}">Borrar</button></div></div>`).join('')}<div class="card-actions">${c.active!==false?`<button class="secondary small-action" data-new-charge="${c.id}">+ Consumo futuro</button>`:''}<button class="secondary small-action" data-statement="${c.id}">Resumen actual</button>${hasStatement?`<button class="text-button small-action" data-delete-statement="${statement.id}">Borrar resumen</button>`:''}<button class="secondary small-action" data-pay-card="${c.id}">Registrar pago</button><button class="text-button small-action" data-toggle-card-active="${c.id}">${c.active===false?'Reactivar':'Dar de baja'}</button><div class="action-total"><span>Consumido para ${formatMonth(nm)}</span><strong>${futureUsd>0?amountPair(future,futureUsd):money(future)}</strong></div></div></div>`}).join('')}</div>`:`<div class="empty"><strong>Agregá tus tarjetas</strong>Podés asociar Visa, Master o Amex a un banco y llevar los consumos de cada mes.</div>`}<p class="footnote">Cada pago parcial se registra por separado con su fecha y cuenta de origen. Las fechas de cierre y vencimiento quedan vacías hasta que las confirmes. Las tarjetas dadas de baja conservan su historial.</p>`}
function dueItems(){let list=[];for(const b of state.bills){if(b.due)list.push({id:b.id,kind:'bill',name:b.name,date:b.due,amount:b.amount,usdAmount:0,detail:'Servicio / gasto',paid:b.paid})}for(const s of state.statements){const c=byId(state.cards,s.cardId);const d=c?dueForCard(c,s.month):{remaining:s.amount,usdTotal:s.usdAmount};if(s.due)list.push({id:s.id,kind:'statement',name:c?.name||'Tarjeta',date:s.due,amount:d.remaining,usdAmount:d.usdTotal,detail:`Resumen ${formatMonth(s.month)}`,paid:d.remaining<=0&&number(d.usdTotal)<=0})}for(const l of state.loans){if(l.due)list.push({id:l.id,kind:'loan',name:l.name,date:l.due,amount:l.installment,usdAmount:0,detail:'Préstamo · próxima cuota',paid:l.paid})}return list.sort((a,b)=>a.date.localeCompare(b.date))}
function renderDues(){const due=dueItems(),pending=due.filter(x=>!x.paid),sum=pending.reduce((n,x)=>n+number(x.amount),0),sumUsd=pending.reduce((n,x)=>n+number(x.usdAmount),0);return `<div class="grid-cards" style="grid-template-columns:repeat(2,minmax(0,1fr));max-width:700px"><div class="metric"><span>Importe pendiente</span><strong>${sumUsd>0?amountPair(sum,sumUsd):money(sum)}</strong></div><div class="metric"><span>Vencimientos pendientes</span><strong>${pending.length}</strong></div></div><div class="section-head"><div><h2>Agenda de pagos</h2><p>Los avisos aparecen al abrir el sitio; podés filtrar por mes desde arriba.</p></div><button class="primary" data-action="new-bill">+ Servicio o gasto</button></div><div class="panel">${rowsOrEmpty(due.filter(d=>d.date.slice(0,7)===selectedMonth).map(d=>`<div class="list-row"><div><strong>${esc(d.name)}</strong><small>${esc(d.detail)} · ${formatDate(d.date)}</small></div><div class="right"><strong>${amountPair(d.amount,d.usdAmount,money(0))}</strong><br><span class="badge ${!d.paid&&d.date<today()?'overdue':''}">${d.paid?'Pagado':d.date<today()?'Vencido':'Pendiente'}</span>${d.kind==='bill'?`<br><button class="text-button small-action" data-toggle-bill="${d.id}">${d.paid?'Marcar pendiente':'Marcar pagado'}</button> <button class="text-button small-action" data-edit-bill="${d.id}">Editar</button> <button class="text-button small-action" data-delete-bill="${d.id}">Borrar</button>`:''}</div></div>`).join(''),'Todavía no hay vencimientos cargados en este mes.')}</div><p class="footnote">El navegador no puede mostrar avisos automáticos cuando el sitio está cerrado. Revisá esta agenda al abrirlo.</p>`}
function renderLoans(){const monthLoans=state.loans.filter(l=>l.due?.slice(0,7)===selectedMonth),monthTotal=monthLoans.reduce((n,l)=>n+number(l.installment),0);return `<div class="section-head"><div><h2>Préstamos</h2><p>Cargá cada préstamo y su próxima cuota. Las cuotas pagadas quedan en Movimientos.</p></div><button class="primary" data-action="new-loan">+ Préstamo</button></div><div class="grid-cards total-grid"><div class="metric"><span>Total de cuotas de ${formatMonth(selectedMonth)}</span><strong>${money(monthTotal)}</strong></div><div class="metric"><span>Cuotas que vencen este mes</span><strong>${monthLoans.length}</strong></div></div>${state.loans.length?`<div class="card-grid">${state.loans.map(l=>`<div class="panel loan-tile" style="--accent:${esc(accountColor(l.accountId))}"><div class="heading"><h3>${esc(l.name)}</h3><small>${esc(accountName(l.accountId))}</small></div><div class="card-stats"><div><span>Próxima cuota</span><strong>${money(l.installment)}</strong></div><div><span>Cuota número</span><strong>${esc(l.current||'—')} / ${esc(l.total||'—')}</strong></div><div><span>Vence</span><strong>${formatDate(l.due)}</strong></div></div><p class="muted" style="font-size:.83rem">${esc(l.member||'')}</p><div class="card-actions"><button class="secondary small-action" data-pay-loan="${l.id}">Registrar pago</button><button class="secondary small-action" data-edit-loan="${l.id}">Editar</button><button class="text-button small-action" data-delete-loan="${l.id}">Borrar</button></div></div>`).join('')}</div>`:`<div class="empty"><strong>No hay préstamos cargados</strong>Podés agregar los préstamos de cada banco o billetera.</div>`}`}
function renderDocuments(){return `<div class="two-col"><div class="panel"><h2>Leer un PDF</h2><p class="muted">Elegí un resumen de tarjeta o una factura de servicios en PDF. Se lee en esta computadora; no se envía a ningún servidor.</p><div class="document-box"><label>Tipo de documento<select id="doc-type"><option value="bill">Factura de servicio</option><option value="card">Resumen de tarjeta</option></select></label><label style="margin-top:1rem">Archivo PDF<input type="file" id="doc-file" accept="application/pdf,.pdf"></label><button class="primary" style="margin-top:1rem" id="read-pdf">Leer documento</button></div><div id="doc-result" style="margin-top:1rem"></div></div><div class="panel"><h2>Revisión antes de guardar</h2><div class="note-list"><div class="hint">Solo se proponen datos reconocidos explícitamente en el texto del PDF. Revisá importes y vencimientos antes de guardarlos.</div><div class="hint">Si el archivo es una imagen escaneada, está protegido o faltan datos, aparece “No se pudo leer”. Podés cargarlos manualmente.</div><div class="hint">El PDF no se guarda en el sitio ni en el respaldo. Solo se conservan los datos que confirmes.</div></div></div></div>`}
function renderSettings(){return `<div class="two-col"><div class="stack"><div class="panel setting-section"><div class="section-head" style="margin:0 0 1rem"><h2>Bancos y billeteras</h2><button class="secondary" data-action="new-account">+ Cuenta</button></div>${state.accounts.map(a=>`<div class="list-row"><div><strong><span class="color-chip" style="background:${esc(a.color)}"></span>${esc(a.name)}</strong><small>Saldo inicial: ${money(a.opening)}${number(a.usdOpening)>0?` · Dólares: ${usd(a.usdOpening)}`:''}${a.cbu?` · CBU/Alias: ${esc(a.cbu)}`:''}${a.debitLast?` · Débito: **** ${esc(a.debitLast)}`:''}</small></div><div class="item-tools"><button data-edit-account="${a.id}">Editar</button>${!state.transactions.some(t=>t.accountId===a.id||t.toAccountId===a.id)&&!state.cards.some(c=>c.accountId===a.id)&&!state.loans.some(l=>l.accountId===a.id)?`<button class="delete" data-delete-account="${a.id}">Borrar</button>`:''}</div></div>`).join('')}</div><div class="panel"><h2>Personas del hogar</h2><p>Asignalas a gastos, ingresos, consumos y préstamos.</p><div>${state.members.map(m=>`<span class="pill" style="margin:.2rem">${esc(m)} <button class="text-button" data-delete-member="${esc(m)}" aria-label="Borrar ${esc(m)}">×</button></span>`).join('')}</div><form id="member-form" style="display:flex;gap:.5rem;margin-top:1rem"><input name="member" required placeholder="Nombre de la persona"><button class="secondary">Agregar</button></form></div><div class="panel"><h2>Cambiar contraseña</h2><p>La contraseña cifra tus datos en este navegador. Elegí una nueva que no aparezca en la dirección del sitio.</p><form id="change-password-form" class="password-form"><label>Contraseña actual<input name="current" type="password" autocomplete="current-password" required></label><label>Contraseña nueva<input name="newPassword" type="password" autocomplete="new-password" minlength="12" required></label><label>Repetir contraseña nueva<input name="confirmPassword" type="password" autocomplete="new-password" minlength="12" required></label><button class="primary">Cambiar contraseña</button><p id="change-password-message" class="fine" role="status">Después descargá un respaldo nuevo: las copias anteriores conservan la contraseña vieja.</p></form></div></div><div class="stack"><div class="panel setting-section"><div class="section-head" style="margin:0 0 1rem"><h2>Rubros de gastos</h2><button class="secondary" data-action="new-category">+ Rubro</button></div><p>Sirven para agrupar gastos en las estadísticas.</p>${state.expenseCategories.map(c=>`<div class="list-row"><strong>${esc(c.name)}</strong><div class="item-tools"><button data-edit-category="${esc(c.id)}">Editar</button><button class="delete" data-delete-category="${esc(c.id)}">Borrar</button></div></div>`).join('')}</div><div class="panel setting-section"><div class="section-head" style="margin:0 0 1rem"><h2>Lugares y servicios</h2><button class="secondary" data-action="new-payee">+ Lugar o servicio</button></div><p>Elegilos al cargar un gasto o una factura, sin escribir el nombre otra vez.</p>${state.payees.map(x=>`<div class="list-row"><div><strong>${esc(x.name)}</strong><small>${esc(categoryName(x.categoryId))}</small></div><div class="item-tools"><button data-edit-payee="${esc(x.id)}">Editar</button><button class="delete" data-delete-payee="${esc(x.id)}">Borrar</button></div></div>`).join('')}</div><div class="panel"><h2>Respaldo cifrado</h2><p>Descargá un archivo cifrado o guardalo en la carpeta de Google Drive de esta computadora. En otra computadora, abrí este sitio, elegí “Importar respaldo” y escribí la contraseña de ese archivo.</p><div class="card-actions"><button class="primary" id="export-backup">Descargar respaldo</button><button class="secondary" id="save-drive-backup">Guardar en Google Drive</button><label class="secondary" style="cursor:pointer">Importar respaldo<input type="file" id="import-backup" accept=".json,application/json" hidden></label></div><p class="fine" style="margin-top:1rem">Si Google Drive está instalado, elegí tu carpeta de Drive cuando se abra “Guardar como”. Drive sincroniza ese archivo después.</p></div><div class="panel"><h2>Cómo se calculan los saldos</h2><p>En Inicio, los meses pasados muestran el saldo al cierre del mes elegido. Los meses futuros muestran solamente movimientos cargados en ese mes.</p><p>Los consumos futuros de tarjeta se mantienen aparte para evitar contarlos dos veces como dinero que salió de una cuenta.</p></div></div></div>`}
function cleanBackupControls(){const input=$('#import-backup');if(!input)return;const panel=input.closest('.panel');panel?.querySelector('#save-drive-backup')?.remove();panel?.querySelector('#open-drive-import')?.remove();const intro=panel?.querySelector('p:not(.fine)');const note=panel?.querySelector('.fine');if(intro)intro.textContent='Descargá un archivo cifrado y guardalo donde prefieras, por ejemplo en tu carpeta de Google Drive. En otra computadora, abrí este sitio, elegí “Importar respaldo” y escribí la contraseña de ese archivo.';if(note)note.textContent='Para llevar solo tus datos a otra computadora, descargá este respaldo e importalo allá. Para llevar también la app actualizada, usá el ZIP nuevo.'}
function modal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();wireModal()}
function close(){ $('#modal').close() }
function formHtml(fields){return `<form id="edit-form"><div class="form-grid">${fields}</div><div class="form-actions"><button type="button" class="secondary" id="cancel-modal">Cancelar</button><button class="primary">Guardar</button></div></form>`}
const field=(label,name,type='text',value='',extra='')=>`<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options)=>`<label>${label}<select name="${name}" required>${options}</select></label>`;
function wireModal(){$('#cancel-modal')?.addEventListener('click',close)}
function submit(handler){$('#edit-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await handler(data);await save();close();render();toast('Guardado correctamente.')}catch(ex){alert(ex.message)}}}
function requireAmount(v){const n=number(v);if(!Number.isFinite(n)||n<=0)throw Error('Ingresá un importe mayor a cero.');return n}
function openTransaction(seed={}){
  const type=seed.kind||'expense';
  const body=formHtml(`${select('Tipo de movimiento','kind',[['expense','Gasto'],['income','Ingreso'],['transfer_out','Transferencia entre cuentas'],['card_payment','Pago de tarjeta'],['loan_payment','Pago de préstamo']].map(([v,n])=>`<option value="${v}" ${v===type?'selected':''}>${n}</option>`).join(''))}${field('Fecha','date','date',seed.date||today(),'required')}${field('Importe en pesos','amount','number',seed.amount||'','required min="0.01" step="0.01"')}${select('Cuenta de origen','accountId',accountOptions(seed.accountId,false,true))}<div id="tx-destination" class="span-all"></div>${field('Detalle','description','text',seed.description||'','placeholder="Ej.: compras de la semana"')}${select('Persona','member',memberOptions(seed.member))}`);
  modal('Nuevo movimiento',body);
  const form=$('#edit-form');
  const update=()=>{
    const t=form.elements.kind.value;
    form.querySelector('#tx-destination').innerHTML=t==='expense'?expenseFields(seed):t==='income'?field('Tipo de ingreso','category','text','','required placeholder="Ej.: sueldo, alquiler, reintegro"'):t==='transfer_out'?select('Cuenta de destino','toAccountId',accountOptions()):t==='card_payment'?`${select('Tarjeta','cardId',cardOptions(seed.cardId,true))}${field('Mes del resumen al que se aplica el pago','statementMonth','month',selectedMonth,'required')}`:t==='loan_payment'?select('Préstamo','loanId','<option value="">Elegí un préstamo</option>'+state.loans.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')):'';
    form.elements.accountId.closest('label').firstChild.textContent=t==='income'?'Cuenta que recibe el ingreso':'Cuenta de origen';
    if(t==='expense')attachCatalogForm(form,'description');
  };
  form.elements.kind.onchange=update;update();
  submit(d=>{
    const amount=requireAmount(d.amount);
    if(!d.accountId)throw Error('Elegí una cuenta.');
    if(d.kind==='expense'&&!d.expenseCategoryId)throw Error('Elegí un rubro de gastos.');
    if(d.kind==='transfer_out'&&(!d.toAccountId||d.toAccountId===d.accountId))throw Error('Elegí otra cuenta de destino.');
    if(d.kind==='card_payment'&&!d.cardId)throw Error('Elegí la tarjeta.');
    if(d.kind==='loan_payment'&&!d.loanId)throw Error('Elegí el préstamo.');
    const payee=d.kind==='expense'?byId(state.payees,d.payeeId):null;
    const t={id:uid(),date:d.date,amount,kind:d.kind,accountId:d.accountId,description:d.description.trim()||payee?.name||({income:'Ingreso',expense:'Gasto',transfer_out:'Transferencia',card_payment:'Pago de tarjeta',loan_payment:'Cuota de préstamo'}[d.kind]),member:d.member,category:d.category?.trim()||'',expenseCategoryId:d.kind==='expense'?d.expenseCategoryId:'',payeeId:d.kind==='expense'?d.payeeId||'':'',cardId:d.cardId||'',loanId:d.loanId||'',statementMonth:d.statementMonth||'',toAccountId:d.toAccountId||''};
    state.transactions.push(t);
    if(d.kind==='transfer_out')state.transactions.push({...t,id:uid(),kind:'transfer_in',accountId:d.toAccountId,toAccountId:d.accountId,linkedId:t.id});
    if(d.kind==='loan_payment')byId(state.loans,d.loanId).paid=true;
  });
}
function expenseFields(item={}){
  return `${select('Rubro de gasto','expenseCategoryId',categoryOptions(item.expenseCategoryId))}<label>Lugar o servicio (opcional)<select name="payeeId">${payeeOptions(item.payeeId)}</select></label>`;
}
function attachCatalogForm(form,descriptionName){
  const selectPayee=form.elements.payeeId;
  if(!selectPayee)return;
  selectPayee.onchange=()=>{
    const payee=byId(state.payees,selectPayee.value);
    if(!payee)return;
    form.elements.expenseCategoryId.value=payee.categoryId;
    const description=form.elements[descriptionName];
    if(description&&!description.value.trim())description.value=payee.name;
  };
}
function openClassifyTransaction(t){
  modal('Clasificar gasto',formHtml(`${expenseFields(t)}${field('Detalle','description','text',t.description||'','required')}`));
  attachCatalogForm($('#edit-form'),'description');
  submit(d=>{
    if(!d.expenseCategoryId)throw Error('Elegí un rubro de gastos.');
    Object.assign(t,{expenseCategoryId:d.expenseCategoryId,payeeId:d.payeeId||'',description:d.description.trim()});
  });
}
function openCategory(c){
  modal(c?'Editar rubro':'Nuevo rubro',formHtml(field('Nombre del rubro','name','text',c?.name||'','required placeholder="Ej.: Mascotas"')));
  submit(d=>{
    const name=d.name.trim();
    if(!name)throw Error('Ingresá un nombre.');
    if(state.expenseCategories.some(x=>x.name.toLocaleLowerCase('es-AR')===name.toLocaleLowerCase('es-AR')&&x.id!==c?.id))throw Error('Ese rubro ya existe.');
    if(c)c.name=name;else state.expenseCategories.push({id:uid(),name});
  });
}
function openPayee(p){
  modal(p?'Editar lugar o servicio':'Nuevo lugar o servicio',formHtml(`${field('Nombre','name','text',p?.name||'','required placeholder="Ej.: Coto, Edenor, AySA"')}${select('Rubro habitual','categoryId',categoryOptions(p?.categoryId))}`));
  submit(d=>{
    const name=d.name.trim();
    if(!name||!d.categoryId)throw Error('Completá el nombre y el rubro.');
    if(state.payees.some(x=>x.name.toLocaleLowerCase('es-AR')===name.toLocaleLowerCase('es-AR')&&x.id!==p?.id))throw Error('Ese lugar o servicio ya existe.');
    if(p)Object.assign(p,{name,categoryId:d.categoryId});else state.payees.push({id:uid(),name,categoryId:d.categoryId});
  });
}
function openAccount(a){modal(a?'Editar cuenta':'Nueva cuenta',formHtml(`${field('Nombre','name','text',a?.name||'','required')}${select('Tipo','type',[['bank','Banco'],['wallet','Billetera virtual'],['cash','Efectivo']].map(([v,n])=>`<option value="${v}" ${a?.type===v?'selected':''}>${n}</option>`).join(''))}${field('CBU o alias (opcional)','cbu','text',a?.cbu||'','placeholder="Ej.: mi.alias.banco"')}${field('Últimos números de débito','debitLast','text',a?.debitLast||'','inputmode="numeric" maxlength="8" placeholder="Ej.: 1234"')}${field('Saldo inicial (pesos)','opening','number',a?.opening||0,'step="0.01" required')}${field('Caja de ahorro en dólares (saldo)','usdOpening','number',number(a?.usdOpening)>0?a.usdOpening:'','min="0" step="0.01" placeholder="Opcional"')}${field('Color','color','color',a?.color||'#3287a5','required')}`));submit(d=>{let obj={name:d.name.trim(),type:d.type,cbu:d.cbu.trim(),debitLast:d.debitLast.trim(),opening:number(d.opening),usdOpening:number(d.usdOpening),color:d.color};if(!obj.name)throw Error('Ingresá un nombre.');if(a)Object.assign(a,obj);else state.accounts.push({id:uid(),...obj})})}
function openCard(c){modal(c?'Editar tarjeta':'Nueva tarjeta',formHtml(`${field('Nombre de la tarjeta','name','text',c?.name||'','required placeholder="Ej.: Visa Santander"')}${select('Banco','accountId',accountOptions(c?.accountId))}${field('Cierre (día del mes, opcional)','closingDay','number',c?.closingDay||'','min="1" max="31"')}${field('Vencimiento habitual (día, opcional)','dueDay','number',c?.dueDay||'','min="1" max="31"')}`));submit(d=>{if(!d.accountId)throw Error('Elegí el banco.');const x={name:d.name.trim(),accountId:d.accountId,closingDay:d.closingDay||'',dueDay:d.dueDay||''};if(c)Object.assign(c,x);else state.cards.push({id:uid(),...x})})}
function openCharge(cardId,existing){
  modal(existing?'Editar consumo':'Consumo del mes siguiente',formHtml(`${select('Tarjeta','cardId',cardOptions(existing?.cardId||cardId))}${field('Mes en que vendrá en el resumen','month','month',existing?.month||nextMonth(selectedMonth),'required')}${field('Fecha de compra (opcional)','date','date',existing?.date||'')}${expenseFields(existing||{})}${field('Comercio o detalle','description','text',existing?.description||'','required')}${field('Importe en pesos','amount','number',number(existing?.amount)>0?existing.amount:'','min="0" step="0.01" placeholder="Si corresponde"')}${field('Importe en dólares','usdAmount','number',number(existing?.usdAmount)>0?existing.usdAmount:'','min="0" step="0.01" placeholder="Opcional"')}${field('Cuotas (opcional)','installment','text',existing?.installment||'','placeholder="Ej.: 3 de 6"')}${select('Persona','member',memberOptions(existing?.member))}`));
  attachCatalogForm($('#edit-form'),'description');
  submit(d=>{
    if(!d.cardId)throw Error('Elegí una tarjeta.');
    if(!existing&&byId(state.cards,d.cardId)?.active===false)throw Error('Esta tarjeta está dada de baja. Reactivala para cargar consumos nuevos.');
    if(!d.expenseCategoryId)throw Error('Elegí un rubro de gastos.');
    const amount=number(d.amount),usdAmount=number(d.usdAmount);
    if(amount<=0&&usdAmount<=0)throw Error('Ingresá un importe en pesos o dólares.');
    const item={...d,amount,usdAmount,description:d.description.trim()};
    if(existing)Object.assign(existing,item);else state.charges.push({id:uid(),...item});
  });
}
function openStatement(cardId,prefill={}){let old=state.statements.find(s=>s.cardId===cardId&&s.month===selectedMonth);modal('Resumen de tarjeta',formHtml(`${select('Tarjeta','cardId',cardOptions(cardId,true))}${field('Mes del resumen','month','month',old?.month||selectedMonth,'required')}${field('Total del resumen en pesos','amount','number',number(old?.amount)>0?old.amount:prefill.amount??'','min="0" step="0.01" placeholder="Si corresponde"')}${field('Total del resumen en dólares','usdAmount','number',number(old?.usdAmount)>0?old.usdAmount:'','min="0" step="0.01" placeholder="Opcional"')}${field('Vencimiento confirmado (opcional)','due','date',old?.due||prefill.due||'')}`));submit(d=>{if(!d.cardId)throw Error('Elegí la tarjeta.');const amount=number(d.amount),usdAmount=number(d.usdAmount);if(amount<=0&&usdAmount<=0)throw Error('Ingresá el total del resumen en pesos o dólares.');let entry=state.statements.find(s=>s.cardId===d.cardId&&s.month===d.month);if(entry)Object.assign(entry,{amount,usdAmount,due:d.due});else state.statements.push({id:uid(),cardId:d.cardId,month:d.month,amount,usdAmount,due:d.due})})}
function openBill(b={}){
  modal(b.id?'Editar vencimiento':'Servicio o gasto',formHtml(`${expenseFields(b)}${field('Nombre','name','text',b.name||'','required placeholder="Ej.: Edenor"')}${field('Importe en pesos','amount','number',b.amount??'','required min="0.01" step="0.01"')}${field('Fecha de vencimiento','due','date',b.due||'','required')}${select('Persona','member',memberOptions(b.member))}`));
  attachCatalogForm($('#edit-form'),'name');
  submit(d=>{
    if(!d.expenseCategoryId)throw Error('Elegí un rubro de gastos.');
    const x={...d,amount:requireAmount(d.amount),paid:b.paid||false};
    if(b.id)Object.assign(b,x);else state.bills.push({id:uid(),...x});
  });
}
function openLoan(l){modal(l?'Editar préstamo':'Nuevo préstamo',formHtml(`${field('Nombre','name','text',l?.name||'','required placeholder="Ej.: Préstamo Santander"')}${select('Cuenta que se usa para pagar','accountId',accountOptions(l?.accountId))}${field('Importe de la cuota','installment','number',l?.installment||'','required min="0.01" step="0.01"')}${field('Próximo vencimiento','due','date',l?.due||'')}${field('Cuota actual','current','number',l?.current||'','min="1"')}${field('Cantidad total de cuotas','total','number',l?.total||'','min="1"')}${select('Persona','member',memberOptions(l?.member))}`));submit(d=>{if(!d.accountId)throw Error('Elegí la cuenta.');let x={...d,installment:requireAmount(d.installment),paid:l?.due===d.due?l.paid:false};if(l)Object.assign(l,x);else state.loans.push({id:uid(),...x})})}
async function readPdf(file){if(!file||!(/\.pdf$/i.test(file.name)||file.type==='application/pdf'))throw Error('Elegí un archivo PDF.');if(file.size>15_000_000)throw Error('El PDF supera 15 MB.');let pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let pages=[];for(let p=1;p<=Math.min(pdf.numPages,20);p++){let page=await pdf.getPage(p),content=await page.getTextContent(),lines=[],lastY=null,line='';for(let item of content.items){if(!('str'in item))continue;let y=Math.round(item.transform[5]);if(lastY!==null&&Math.abs(y-lastY)>3){if(line.trim())lines.push(line.trim());line=''}line+=item.str+' ';lastY=y}if(line.trim())lines.push(line.trim());pages.push(lines.join('\n'))}await pdf.destroy();return pages.join('\n')}
const parseMoney=s=>{let x=s.replace(/[^\d.,]/g,'');if(!x)return null;let i=x.lastIndexOf(','),j=x.lastIndexOf('.');if(i>=0&&j>=0)x=i>j?x.replace(/\./g,'').replace(',','.'):x.replace(/,/g,'');else if(i>=0)x=x.replace(/\./g,'').replace(',','.');else if(j>=0){let parts=x.split('.');if(parts.at(-1).length===3)x=x.replace(/\./g,'')}let n=Number(x);return Number.isFinite(n)&&n>0?n:null};
function dateFrom(s){let m=s.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})/);if(!m)return '';let y=Number(m[3]);if(y<100)y+=2000;let dt=new Date(y,Number(m[2])-1,Number(m[1]));return dt.getFullYear()===y&&dt.getMonth()===Number(m[2])-1&&dt.getDate()===Number(m[1])?`${y}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`:''}
function parseDoc(text,type){const lines=text.split('\n').map(x=>x.trim()).filter(Boolean);let names=['AySA','Edenor','Metrogas','Naturgy','Flow','Personal','Movistar','Municipalidad','ARBA','Telecentro','Edesur','Camuzzi'];let name=names.find(n=>new RegExp(n,'i').test(text))||'';let amt=[],dates=[];for(let i=0;i<lines.length;i++){let line=lines[i];if(/(?:total\s+a\s+pagar|importe\s+total|total\s+del\s+resumen|saldo\s+total)/i.test(line)){let m=line.match(/\$\s*([\d.,]+)/)||lines[i+1]?.match(/^\$\s*([\d.,]+)/);if(m){let n=parseMoney(m[1]);if(n)amt.push({amount:n,source:line.slice(0,160)})}}if(/(?:fecha\s+de\s+vencimiento|vencimiento(?:\s+actual)?|1[°ºer]*\s*vencimiento)/i.test(line)){let d=dateFrom(line)||dateFrom(lines[i+1]||'');if(d)dates.push({date:d,source:line.slice(0,160)})}}let uniqueAmt=[...new Set(amt.map(x=>x.amount))],uniqueDate=[...new Set(dates.map(x=>x.date))];return {name,amount:uniqueAmt.length===1?uniqueAmt[0]:null,due:uniqueDate.length===1?uniqueDate[0]:'',ambiguous:uniqueAmt.length>1||uniqueDate.length>1,source:[...amt,...dates].map(x=>x.source).slice(0,8),textLength:text.trim().length,type}}
function wire(){const root=$('#view');root.onclick=async e=>{let el=e.target.closest('button');if(!el)return;const d=el.dataset;if(el.id==='export-backup'){await downloadBackup();return}else if(d.go){view=d.go;render()}else if(d.toggleHomeAmounts){homeAmountsVisible=!homeAmountsVisible;render()}else if(d.action==='new-transaction')openTransaction();else if(d.action==='new-card')openCard();else if(d.action==='new-account')openAccount();else if(d.action==='new-category')openCategory();else if(d.action==='new-payee')openPayee();else if(d.action==='new-bill')openBill();else if(d.action==='new-loan')openLoan();else if(d.editAccount)openAccount(byId(state.accounts,d.editAccount));else if(d.editCategory)openCategory(byId(state.expenseCategories,d.editCategory));else if(d.editPayee)openPayee(byId(state.payees,d.editPayee));else if(d.classifyTx)openClassifyTransaction(byId(state.transactions,d.classifyTx));else if(d.editCharge)openCharge('',byId(state.charges,d.editCharge));else if(d.editBill)openBill(byId(state.bills,d.editBill));else if(d.editCard)openCard(byId(state.cards,d.editCard));else if(d.toggleCardActive){let c=byId(state.cards,d.toggleCardActive);if(c&&(c.active===false||confirm('¿Dar de baja esta tarjeta? Conserva todos los consumos, resúmenes y pagos anteriores.'))){c.active=c.active===false;await save();render()}}else if(d.newCharge)openCharge(d.newCharge);else if(d.statement)openStatement(d.statement);else if(d.deleteStatement){let s=byId(state.statements,d.deleteStatement);if(s&&confirm(`¿Borrar el resumen de ${cardName(s.cardId)} de ${formatMonth(s.month)}? Los pagos cargados para ese resumen se conservan como movimientos.`)){state.statements=state.statements.filter(x=>x.id!==s.id);await save();render()}}else if(d.payCard)openTransaction({kind:'card_payment',cardId:d.payCard});else if(d.payLoan){let l=byId(state.loans,d.payLoan);openTransaction({kind:'loan_payment',accountId:l.accountId,amount:l.installment,description:`Cuota ${l.name}`})}else if(d.editLoan)openLoan(byId(state.loans,d.editLoan));else if(d.deleteCategory){let id=d.deleteCategory;if(state.payees.some(x=>x.categoryId===id)||state.transactions.some(x=>x.expenseCategoryId===id)||state.charges.some(x=>x.expenseCategoryId===id)||state.bills.some(x=>x.expenseCategoryId===id)){alert('Este rubro ya se usa. Cambiá el rubro de esos registros antes de borrarlo.')}else if(confirm('¿Borrar este rubro?')){state.expenseCategories=state.expenseCategories.filter(x=>x.id!==id);await save();render()}}else if(d.deletePayee){let id=d.deletePayee;if(state.transactions.some(x=>x.payeeId===id)||state.charges.some(x=>x.payeeId===id)||state.bills.some(x=>x.payeeId===id)){alert('Este lugar o servicio ya se usa. Cambiá esos registros antes de borrarlo.')}else if(confirm('¿Borrar este lugar o servicio?')){state.payees=state.payees.filter(x=>x.id!==id);await save();render()}}else if(d.deleteTx){let t=byId(state.transactions,d.deleteTx);if(confirm(`¿Borrar ${t.description} por ${money(t.amount)}?`)){const sourceId=t.linkedId||t.id;state.transactions=state.transactions.filter(x=>x.id!==sourceId&&x.linkedId!==sourceId);await save();render()}}else if(d.deleteCharge){if(confirm('¿Borrar este consumo futuro?')){state.charges=state.charges.filter(x=>x.id!==d.deleteCharge);await save();render()}}else if(d.toggleBill){let b=byId(state.bills,d.toggleBill);b.paid=!b.paid;await save();render()}else if(d.deleteBill){if(confirm('¿Borrar este vencimiento?')){state.bills=state.bills.filter(x=>x.id!==d.deleteBill);await save();render()}}else if(d.deleteLoan){if(confirm('¿Borrar este préstamo?')){state.loans=state.loans.filter(x=>x.id!==d.deleteLoan);await save();render()}}else if(d.deleteAccount){if(confirm('¿Borrar esta cuenta?')){state.accounts=state.accounts.filter(x=>x.id!==d.deleteAccount);await save();render()}}else if(d.deleteMember){if(confirm('¿Borrar esta persona de la lista? Los movimientos anteriores conservarán su nombre.')){state.members=state.members.filter(x=>x!==d.deleteMember);await save();render()}}};
const acc=$('#filter-account'),kind=$('#filter-kind');if(acc&&kind){let filter=()=>{let arr=state.transactions.filter(t=>inMonth(t)&&(t.kind!=='transfer_in'||!!acc.value)).sort((a,b)=>b.date.localeCompare(a.date));if(acc.value)arr=arr.filter(t=>t.accountId===acc.value);if(kind.value)arr=arr.filter(t=>t.kind===kind.value);$('#tx-results').innerHTML=txTable(arr)};acc.onchange=kind.onchange=filter}
$('#member-form')?.addEventListener('submit',async e=>{e.preventDefault();let x=e.target.elements.member.value.trim();if(x&&!state.members.includes(x)){state.members.push(x);await save();render()}});
$('#change-password-form')?.addEventListener('submit',async e=>{
  e.preventDefault();
  const form=e.currentTarget,button=form.querySelector('button'),message=$('#change-password-message');
  const current=form.elements.current.value,next=form.elements.newPassword.value,again=form.elements.confirmPassword.value;
  message.className='error';message.textContent='';
  if(next.length<12){message.textContent='Usá al menos 12 caracteres.';return}
  if(next!==again){message.textContent='Las contraseñas nuevas no coinciden.';return}
  if(next===current){message.textContent='La contraseña nueva debe ser diferente.';return}
  button.disabled=true;
  try{
    await unlocked(JSON.parse(localStorage.getItem(KEY)),current);
    const newSalt=crypto.getRandomValues(new Uint8Array(16)),newKey=await derive(next,newSalt);
    const blob=await encrypted(state,newKey,newSalt);
    localStorage.setItem(KEY,JSON.stringify(blob));
    secret=newKey;salt=newSalt;
    form.reset();message.className='fine';message.textContent='Contraseña cambiada. Descargá un respaldo nuevo; los anteriores siguen usando la contraseña vieja.';
    toast('Contraseña cambiada y datos cifrados nuevamente.');
  }catch(ex){message.textContent=ex.name==='OperationError'?'La contraseña actual no es correcta.':'No se pudo guardar el cambio: '+ex.message}
  finally{button.disabled=false}
});
async function backupFile(){await save();return {name:`hogar-respaldo-${today()}.json`,content:localStorage.getItem(KEY)}}
function downloadBackupFile(name,content){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function downloadBackup(){const f=await backupFile();downloadBackupFile(f.name,f.content)}
async function importBackupFile(file){if(!file)return;let raw=JSON.parse(await file.text()),pass=prompt('Contraseña con la que se creó este respaldo:');if(pass===null)return;let result=await unlocked(raw,pass);if(!confirm('Esto reemplazará TODOS los datos de esta computadora por los del respaldo. ¿Continuar?'))return;state=result.data;secret=result.key;salt=result.s;localStorage.setItem(KEY,JSON.stringify(raw));render();toast('Respaldo importado.')}
async function importBackupChange(e){try{await importBackupFile(e.target.files?.[0])}catch(ex){alert(ex.name==='OperationError'?'Contraseña incorrecta o archivo dañado.':ex.message)}finally{e.target.value=''}}
$('#export-backup')?.addEventListener('click',downloadBackup);
$('#import-backup')?.addEventListener('change',importBackupChange);
$('#read-pdf')?.addEventListener('click',async()=>{let file=$('#doc-file').files?.[0],type=$('#doc-type').value,out=$('#doc-result');out.innerHTML='<p class="muted">Leyendo el PDF…</p>';try{let content=await readPdf(file),parsed=parseDoc(content,type);if(!parsed.textLength||!parsed.amount||!parsed.due||parsed.ambiguous||type==='bill'&&!parsed.name){out.innerHTML=`<div class="hint"><strong>No se pudo leer con seguridad.</strong> Puede ser un PDF escaneado, tener varios totales o faltar un importe, proveedor o vencimiento inequívoco. Cargalo manualmente; no se guardó ningún dato.</div><details style="margin-top:1rem"><summary>Ver texto extraído (${content.length} caracteres)</summary><div class="review">${esc(content.slice(0,9000)||'Sin texto seleccionable.')}</div></details>`;return}docDraft=parsed;let options=type==='card'?`${select('Tarjeta','doc-card',cardOptions())}${field('Mes del resumen','doc-month','month',selectedMonth)}`:'';out.innerHTML=`<div class="hint"><strong>Datos encontrados; confirmalos antes de guardar.</strong><br>Importe: ${money(parsed.amount)} · Vence: ${formatDate(parsed.due)}${parsed.name?` · ${esc(parsed.name)}`:''}</div><div class="review" style="margin-top:.8rem">Texto que permitió identificar los datos:\n${esc(parsed.source.join('\n'))}</div><div style="margin-top:.8rem">${options}<button class="primary" id="confirm-document" style="margin-top:.8rem">Confirmar y guardar</button></div><details style="margin-top:1rem"><summary>Ver texto extraído</summary><div class="review">${esc(content.slice(0,9000))}</div></details>`;$('#confirm-document').onclick=async()=>{if(type==='card'){let id=out.querySelector('[name="doc-card"]').value,m=out.querySelector('[name="doc-month"]').value;if(!id||!m){alert('Elegí la tarjeta y el mes.');return}if(state.statements.some(s=>s.cardId===id&&s.month===m)){alert('Ya existe un resumen para esta tarjeta y mes. Editalo desde Tarjetas.');return}state.statements.push({id:uid(),cardId:id,month:m,amount:parsed.amount,due:parsed.due})}else state.bills.push({id:uid(),name:parsed.name,amount:parsed.amount,due:parsed.due,member:state.members[0]||'Yo',paid:false,payeeId:state.payees.find(p=>p.name.toLocaleLowerCase('es-AR')===parsed.name.toLocaleLowerCase('es-AR'))?.id||'',expenseCategoryId:state.payees.find(p=>p.name.toLocaleLowerCase('es-AR')===parsed.name.toLocaleLowerCase('es-AR'))?.categoryId||''});await save();render();toast('Documento confirmado y guardado.')}}catch(ex){out.innerHTML=`<div class="hint"><strong>No se pudo leer.</strong> ${esc(ex.message||'El archivo no se pudo procesar.')} No se guardó ningún dato.</div>`}})
}

// An online first visit stores the static application shell for later offline visits.
function updateConnection(ready=false){
  const status=$('#connection-status');
  if(!navigator.onLine){status.textContent='Sin conexión · podés seguir cargando datos';status.dataset.mode='offline'}
  else if(ready){status.textContent='Disponible sin conexión en este equipo';status.dataset.mode='ready'}
  else{status.textContent='Preparando uso sin conexión…';status.dataset.mode='preparing'}
}
if('serviceWorker' in navigator){
  let offlineReady=false;
  updateConnection();
  navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{
    offlineReady=true;updateConnection(true);
  }).catch(()=>{
    $('#connection-status').textContent='No se pudo preparar el uso sin conexión';
  });
  window.addEventListener('online',()=>updateConnection(offlineReady));
  window.addEventListener('offline',()=>updateConnection(offlineReady));
}else $('#connection-status').textContent='Este navegador requiere internet para abrir el sitio';
